import { Component } from '@angular/core';
import { LogoCarouselComponent } from '@conciso/design-system-angular';

@Component({
  selector: 'app-demo',
  imports: [LogoCarouselComponent],
  template: `
    <cds-logo-carousel
        [interval]="6000"
        [active]="0"
        [sets]="[[{label: 'NORDWIND'}, {label: 'MERIDIAN'}, {label: 'AVERA'}, {label: 'KONTUR'}, {label: 'STELLA'}], [{label: 'VOLTAIC'}, {label: 'HEXAGON'}, {label: 'LUMEN'}, {label: 'PRAXIS'}, {label: 'ORBIT'}], [{label: 'CASCADE'}, {label: 'VERTEX'}, {label: 'NIMBUS'}, {label: 'FORGE'}, {label: 'ATLAS'}]]"
        (activeChange)="activeChange($event)"
    />`,
})
export class DemoComponent {
  activeChange(event: unknown) {}
}

